{
  "command": "cat 'C:/Users/loidi/.pi/agent/evcrate/workflows/development-rules.md'; python 'C:/Users/loidi/.pi/agent/evcrate/scripts/generate_catalogs.py' --skills; python 'C:/Users/loidi/.pi/agent/evcrate/scripts/generate_catalogs.py' --commands",
  "timeout": 120
}

{
  "command": "git status --short; git rev-parse --show-toplevel; Get-ChildItem -Force | Select-Object Name,Mode,Length; Get-ChildItem -Recurse -File -Filter codebase-summary.md | Select-Object -ExpandProperty FullName",
  "timeout": 120
}

{
  "command": "cat 'C:/Users/loidi/.pi/agent/evcrate/skills/debugging/SKILL.md'; printf '\\n--- root ---\\n'; find . -maxdepth 3 -type f \\( -name Cargo.toml -o -name Cargo.lock -o -name '*.dmp' -o -name '*.log' \\) -print | sort",
  "timeout": 120
}

{
  "command": "find apps/native/src-tauri -maxdepth 3 -type f \\( -name 'Cargo.toml' -o -name 'Cargo.lock' -o -name '*.rs' \\) -print | sort | head -100; find apps/native/src-tauri/target -type f -iname '*test*.exe' -o -type f -name '*.exe' 2>/dev/null | head -100; find artifacts -type f -maxdepth 3 -print 2>/dev/null | sort",
  "timeout": 120
}

{
  "command": "command -v dumpbin || true; command -v objdump || true; command -v llvm-objdump || true; command -v cargo || true; rustc -Vv 2>&1; cargo -V 2>&1; uname -a",
  "timeout": 120
}

{
  "command": "find 'C:/Users/loidi/.pi/agent' -path '*debugging*SKILL.md' -print; find apps/native/src-tauri/target/debug/deps -maxdepth 1 -type f -name '*.exe' -printf '%f\\n' | sort | tail -80",
  "timeout": 120
}

{
  "command": "sed -n '1,240p' apps/native/src-tauri/Cargo.toml; printf '\\n--- relevant lock packages ---\\n'; grep -nE 'name = \"(tauri|wry|webview2|windows|windows-sys|ssh2|russh|libssh2-sys|openssl-sys|ring|tokio|serde)\"|version = ' apps/native/src-tauri/Cargo.lock | head -240; printf '\\n--- evidence ---\\n'; cat artifacts/native-browser-debug/windows-evidence.json",
  "timeout": 120
}

{
  "command": "find apps/native/src-tauri/target -type f \\( -iname '*.exe' -o -iname '*.dll' \\) -printf '%TY-%Tm-%Td %TH:%TM %s %p\\n' | sort -r | head -150; printf '\\n--- recent logs ---\\n'; find . -path './.git' -prune -o -type f \\( -iname '*.log' -o -iname '*.txt' \\) -printf '%TY-%Tm-%Td %TH:%TM %s %p\\n' -print 2>/dev/null | sort -r | head -100",
  "timeout": 120
}

